def semver_sort(versions):
    def parse(v):
        # split off build metadata
        main_pre = v.split('+', 1)[0]
        if '-' in main_pre:
            idx = main_pre.index('-')
            core = main_pre[:idx]
            pre = main_pre[idx+1:]
            has_pre = True
        else:
            core = main_pre
            pre = ''
            has_pre = False
        parts = core.split('.')
        major, minor, patch = (int(p) for p in parts[:3])

        pre_key = []
        if has_pre:
            for ident in pre.split('.'):
                if ident.isdigit():
                    pre_key.append((0, int(ident)))
                else:
                    pre_key.append((1, ident))

        # presence flag: has_pre=True sorts before False
        presence = 0 if has_pre else 1

        return (major, minor, patch, presence, pre_key)

    return sorted(versions, key=parse)

